"""

# command -> (positional counts allowed, takes --json, takes --format)
COMMANDS = {
    "stock": ((0,), True, False),
    "low": ((0,), True, False),
    "history": ((1,), True, False),
    "receive": ((3, 4), False, False),
    "ship": ((3, 4), False, False),
    "quote": ((1,), True, False),
    "fulfil": ((2,), False, False),
    "invoice": ((1,), True, False),
    "report": ((0,), False, True),
}
FREE_FORM = ("receive", "ship", "fulfil")
FILES_NEEDED = {
    "stock": (CATALOG, MOVEMENTS),
    "low": (CATALOG, MOVEMENTS),
    "history": (CATALOG, MOVEMENTS),
    "receive": (CATALOG, MOVEMENTS),
    "ship": (CATALOG, MOVEMENTS),
    "quote": (CATALOG, ORDERS),
    "fulfil": (CATALOG, MOVEMENTS, ORDERS),
    "invoice": (CATALOG, MOVEMENTS, ORDERS),
    "report": (CATALOG, MOVEMENTS, ORDERS),
}


class UsageError(Exception):
    """Something is wrong with the command line (exit 2)."""


class FileProblem(Exception):
    """A file cannot be read (exit 2)."""


class DataProblem(Exception):
    """A mistake in a data file (exit 1)."""


class Request(object):
    def __init__(self):
        self.directory = "."
        self.command = None
        self.json = False
        self.format = "text"
        self.args = []


def parse_command_line(argv):
    req = Request()
    rest = []
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--dir":
            if i + 1 >= len(argv):
                raise UsageError("--dir needs a value")
            req.directory = argv[i + 1]
            i += 2
        elif arg.startswith("--dir="):
            req.directory = arg[len("--dir="):]
            i += 1
        else:
            rest.append(arg)
            i += 1

    index = None
    for n, arg in enumerate(rest):
        if arg == "-" or not arg.startswith("-"):
            index = n
            break
    if index is None:
        raise UsageError("no command given")
    command = rest[index]
    if command not in COMMANDS:
        raise UsageError("unknown command %r" % command)
    counts, takes_json, takes_format = COMMANDS[command]
    req.command = command
    before, after = rest[:index], rest[index + 1:]

    if command in FREE_FORM:
        if before:
            raise UsageError("unknown option %r" % before[0])
        positional = after
    else:
        positional = []
        args = before + after
        j = 0
        while j < len(args):
            arg = args[j]
            if arg == "--json" and takes_json:
                req.json = True
            elif arg == "--format" and takes_format:
                if j + 1 >= len(args):
                    raise UsageError("--format needs a value")
                req.format = args[j + 1]
                j += 1
            elif arg.startswith("--format=") and takes_format:
                req.format = arg[len("--format="):]
            elif arg.startswith("-") and arg != "-":
                raise UsageError("unknown option %r" % arg)
            else:
                positional.append(arg)
            j += 1
        if req.format not in ("text", "csv", "json"):
            raise UsageError("bad --format value %r (text, csv or json)" % req.format)

    if len(positional) not in counts:
        raise UsageError(
            "wrong number of arguments for %s (got %d)" % (command, len(positional))
        )
    if command in ("receive", "ship") and parse_date(positional[0]) is None:
        raise UsageError("bad date %r (expected YYYY-MM-DD)" % positional[0])
    if command == "fulfil" and parse_date(positional[1]) is None:
        raise UsageError("bad date %r (expected YYYY-MM-DD)" % positional[1])
    req.args = positional
    return req
